// Frieren's TranscriptImage resolver: a tool-result `src` is a Volume path (the
// agent offloads generated bytes to /pictures, #194); the browser reads it from
// the local synced replica and hands the Transcript an object URL. The DO's write
// reaches the replica via sync, which can lag a beat behind the tool result —
// hence the flush-and-retry cycle on first sight of a src.
import type { TranscriptImage } from '@justfiles/ui/Transcript'
import { openProfile } from '../fs'

// Bound the cache: each object URL pins its backing Blob in memory, so a
// long-lived tab evicts (and revokes) the oldest entries past the cap. An
// evicted src still on screen just re-resolves on its next render.
const MAX_CACHED = 48
const cache = new Map<string, Promise<string | null>>()

// Srcs that already failed a full flush-and-retry cycle. The card keeps retrying
// while visible, but for a known miss each retry is a single cheap read — a
// deleted file never comes back, and a late sync lands via the regular pull.
const missed = new Set<string>()

export function resolveTranscriptImage(image: TranscriptImage): Promise<string | null> {
	const cached = cache.get(image.src)
	if (cached) return cached
	const load = (async () => {
		const volume = await openProfile()
		const attempts = missed.has(image.src) ? 1 : 10
		for (let attempt = 0; ; attempt++) {
			try {
				const bytes = await volume.readFile(image.src)
				missed.delete(image.src)
				return URL.createObjectURL(new Blob([bytes as BlobPart], { type: image.mimeType }))
			} catch {
				if (attempt + 1 >= attempts) {
					missed.add(image.src)
					return null
				}
				// Not replicated yet — force a sync cycle rather than waiting out the
				// regular interval, then give the pull a moment to land.
				await volume.flush().catch(() => {})
				await new Promise((resolve) => setTimeout(resolve, 1500))
			}
		}
	})()
	cache.set(image.src, load)
	// A miss is not cached, so the card's next attempt reaches the volume again.
	void load.then((url) => {
		if (url === null) cache.delete(image.src)
		else evict()
	})
	return load
}

function evict(): void {
	for (const [src, entry] of cache) {
		if (cache.size <= MAX_CACHED) return
		cache.delete(src)
		void entry.then((url) => url && URL.revokeObjectURL(url))
	}
}
